// Format writes an amount held in hundredths with two decimals: Format(-123456) is "-1234.56".
func Format(v int64) string {
	sign := ""
	u := uint64(v)
	if v < 0 {
		sign = "-"
		u = uint64(-v)
	}
	frac := strconv.FormatUint(u%100, 10)
	if len(frac) < 2 {
